<script setup lang="ts">
import type { OrgNode } from '~/types/organization'
defineProps<{ node: OrgNode, depth: number, expanded: Set<string>, selectedId?: string }>()
const emit = defineEmits<{ select: [node: OrgNode], toggle: [id: string] }>()
</script>
<template><div class="tree-node"><div class="tree-row" :class="{ 'is-selected': selectedId === node.id, 'is-group': node.children?.length }" :style="{ '--tree-depth': depth }" @click="emit('select', node)"><span class="tree-indent" /><button v-if="node.children?.length" type="button" class="tree-toggle" @click.stop="emit('toggle', node.id)"><UIcon :name="expanded.has(node.id) ? 'i-lucide-chevron-down' : 'i-lucide-chevron-right'" size="13" /></button><span v-else style="width: 22px" /><UIcon :name="node.unitType === 'COMPANY' ? 'i-lucide-building-2' : node.unitType === 'DEPARTMENT' ? 'i-lucide-network' : 'i-lucide-users'" size="14" :style="{ color: node.unitType === 'COMPANY' ? '#246bfd' : '#72829a' }" /><div class="tree-label"><b>{{ node.name }}</b><small>{{ node.memberCount }} 人 · {{ node.positionCount }} 岗位</small></div></div><div v-if="node.children?.length && expanded.has(node.id)" class="tree-children" :style="{ '--tree-parent-depth': depth }"><OrgManagementTreeBranch v-for="child in node.children" :key="child.id" :node="child" :depth="depth + 1" :expanded="expanded" :selected-id="selectedId" @select="emit('select', $event)" @toggle="emit('toggle', $event)" /></div></div></template>
